  ('f403a315-c18f-427a-84d3-8443f6c1271e', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '0bff18e3-0eee-4a1a-8449-b4728a8c8b46', 'concept'::public.curated_course_node_type, 'Diversity, equity, inclusion, belonging, and accessibility', null, 0),
  ('c4529925-f6c7-4dab-b56a-11d6a0e1ea4e', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '0bff18e3-0eee-4a1a-8449-b4728a8c8b46', 'concept'::public.curated_course_node_type, 'Bias, harassment, discrimination, and respectful workplace expectations', null, 1),
  ('9ce8d1fd-ea98-49d1-b043-770bf6857d04', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '0bff18e3-0eee-4a1a-8449-b4728a8c8b46', 'concept'::public.curated_course_node_type, 'Wages, tips, benefits, scheduling, labor rights, and ethical recruitment awareness', null, 2),
  ('1840dff7-9108-460d-9ecd-a3977ea0d5a1', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '0bff18e3-0eee-4a1a-8449-b4728a8c8b46', 'concept'::public.curated_course_node_type, 'Emotional labor, burnout, safety, well-being, and speaking up', null, 3),
  ('b9e59208-d4d6-4ca4-8fed-dd45d7674f1b', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', null, 'topic'::public.curated_course_node_type, 'Sustainability, Accessibility, Community, and Social Responsibility', 'Connects environmental performance, community value, cultural respect, universal design, responsible sourcing, human rights, and credible reporting to hospitality decisions.', 12),
  ('82772413-cb2c-49fd-b4cb-6e7e0163e1a2', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'b9e59208-d4d6-4ca4-8fed-dd45d7674f1b', 'subtopic'::public.curated_course_node_type, 'Environmental operations', 'Hospitality organizations can reduce cost and impact through disciplined resource management and design.', 0),
  ('ad6a5893-ecec-440d-a740-16365d0137d6', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '82772413-cb2c-49fd-b4cb-6e7e0163e1a2', 'concept'::public.curated_course_node_type, 'Energy, water, refrigerants, and carbon', null, 0),
  ('c7a21a7a-fc8b-47e1-8ae4-691c631caaa9', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '82772413-cb2c-49fd-b4cb-6e7e0163e1a2', 'concept'::public.curated_course_node_type, 'Food waste, materials, single-use items, and circularity', null, 1),
  ('992544f1-5622-46b1-b607-857684cc7f60', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '82772413-cb2c-49fd-b4cb-6e7e0163e1a2', 'concept'::public.curated_course_node_type, 'Sustainable food, seafood, amenities, and procurement', null, 2),
  ('2eeba8ac-31ac-4db4-bb7d-55223fdfed9c', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '82772413-cb2c-49fd-b4cb-6e7e0163e1a2', 'concept'::public.curated_course_node_type, 'Buildings, transport, biodiversity, and climate resilience', null, 3),
  ('4213e7f2-5b17-4d92-903e-ae4952842d11', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'b9e59208-d4d6-4ca4-8fed-dd45d7674f1b', 'subtopic'::public.curated_course_node_type, 'Accessibility and inclusive service', 'Universal design expands participation and improves service for guests with varied bodies, senses, cognition, language, and circumstances.', 1),
  ('172e4f01-d4e5-40d7-ae6d-f6cfeef90d10', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '4213e7f2-5b17-4d92-903e-ae4952842d11', 'concept'::public.curated_course_node_type, 'Physical, sensory, cognitive, digital, and communication access', null, 0);
