  ('32a1f5ba-f43f-4104-8f0f-9ca3e42dfc7b', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5ed47b2a-9f7e-4467-ae41-1a8120ec1f89', 'concept'::public.curated_course_node_type, 'Human trafficking awareness, child protection, and supply-chain human rights', null, 2),
  ('e1e21fec-b8f3-4d59-8252-94f0fd82222f', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5ed47b2a-9f7e-4467-ae41-1a8120ec1f89', 'concept'::public.curated_course_node_type, 'Targets, evidence, reporting, certification, and greenwashing', null, 3),
  ('86e637ca-e625-4203-aeea-a2eeb34802b9', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', null, 'topic'::public.curated_course_node_type, 'Hospitality Technology, Data, AI, Cybersecurity, and Innovation', 'Surveys the digital stack and develops judgment about usefulness, integration, privacy, security, accessibility, automation, AI, and responsible innovation.', 13),
  ('cf068406-d6c6-422c-927a-6762aba76265', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '86e637ca-e625-4203-aeea-a2eeb34802b9', 'subtopic'::public.curated_course_node_type, 'Hospitality technology stack', 'Students need a functional map of systems before learning individual products.', 0),
  ('b3375dcf-a8b2-4cb0-ad95-8d19b3356adc', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'cf068406-d6c6-422c-927a-6762aba76265', 'concept'::public.curated_course_node_type, 'PMS, POS, CRS, booking engine, channel manager, and GDS', null, 0),
  ('bce1d4ed-cf71-495c-8a84-b9e15f75f2ae', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'cf068406-d6c6-422c-927a-6762aba76265', 'concept'::public.curated_course_node_type, 'CRM, loyalty, revenue, workforce, finance, procurement, and maintenance systems', null, 1),
  ('a0da1616-4bb0-4f14-872e-b52816114767', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'cf068406-d6c6-422c-927a-6762aba76265', 'concept'::public.curated_course_node_type, 'Payments, mobile keys, kiosks, messaging, IoT, and guest-room technology', null, 2),
  ('916c52a1-1333-45dc-ab78-97cc6528a07a', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'cf068406-d6c6-422c-927a-6762aba76265', 'concept'::public.curated_course_node_type, 'Interfaces, APIs, integration, vendor dependence, and data quality', null, 3),
  ('5e2e16bd-d7f3-436a-859f-d285b0861230', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '86e637ca-e625-4203-aeea-a2eeb34802b9', 'subtopic'::public.curated_course_node_type, 'Data, analytics, and AI', 'Data can improve service and decisions when its meaning, quality, limits, and permissions are understood.', 1),
  ('cfe70a9d-6863-4703-8319-1870e2e819a3', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e2e16bd-d7f3-436a-859f-d285b0861230', 'concept'::public.curated_course_node_type, 'Operational, guest, transaction, workforce, and market data', null, 0),
  ('625d08c8-9dd4-4417-a770-b44e5677b40b', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e2e16bd-d7f3-436a-859f-d285b0861230', 'concept'::public.curated_course_node_type, 'Descriptive, diagnostic, predictive, and prescriptive analytics awareness', null, 1),
  ('39af8f95-dc82-4a41-8855-9fa4facff13e', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e2e16bd-d7f3-436a-859f-d285b0861230', 'concept'::public.curated_course_node_type, 'Forecasting, personalization, chatbots, content, and automation use cases', null, 2),
  ('e4e2dec7-4396-480c-90af-00a5bb291a7e', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e2e16bd-d7f3-436a-859f-d285b0861230', 'concept'::public.curated_course_node_type, 'Bias, hallucination, transparency, human oversight, and measurement', null, 3),
  ('5e3750fa-228a-4e80-bbad-4abc50783171', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '86e637ca-e625-4203-aeea-a2eeb34802b9', 'subtopic'::public.curated_course_node_type, 'Cybersecurity, privacy, and innovation', 'Hospitality''s many systems, payments, identities, and connected devices create material digital risk.', 2),
  ('ac4b3d12-1fc4-4a88-85b0-ba51ac296f98', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e3750fa-228a-4e80-bbad-4abc50783171', 'concept'::public.curated_course_node_type, 'Phishing, ransomware, payment, identity, and IoT risks', null, 0),
  ('d0ca82a9-3733-410f-9392-a4ac6a00442c', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e3750fa-228a-4e80-bbad-4abc50783171', 'concept'::public.curated_course_node_type, 'Access control, updates, backups, incident reporting, and vendor risk', null, 1),
  ('6423e068-ea1c-4246-b3e7-60a34589f1df', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e3750fa-228a-4e80-bbad-4abc50783171', 'concept'::public.curated_course_node_type, 'Consent, minimization, retention, sharing, and guest rights awareness', null, 2),
  ('f03c1f3d-6951-41d3-b4f2-56c747344804', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5e3750fa-228a-4e80-bbad-4abc50783171', 'concept'::public.curated_course_node_type, 'Problem discovery, pilots, change management, adoption, and responsible scaling', null, 3),
  ('bb8da051-20e7-4acd-ae38-957464a4937e', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', null, 'topic'::public.curated_course_node_type, 'Safety, Hygiene, Law, Ethics, Risk, and Crisis Readiness', 'Establishes duty of care and the operational disciplines that protect guests, employees, organizations, and communities during routine service and disruption.', 14),
  ('2be3a52b-bab9-4b6c-8a48-0272829e195a', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'bb8da051-20e7-4acd-ae38-957464a4937e', 'subtopic'::public.curated_course_node_type, 'Hygiene, food safety, and public health', 'Safe hospitality requires preventive systems, trained people, clean facilities, and reliable response.', 0),
  ('dfbfde5b-ec90-4ee7-9a0c-6adf1eadde4a', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '2be3a52b-bab9-4b6c-8a48-0272829e195a', 'concept'::public.curated_course_node_type, 'Personal hygiene, cleaning, sanitation, and pest control', null, 0),
  ('980a24b3-671c-4a5e-85e5-c5d9c21fe265', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '2be3a52b-bab9-4b6c-8a48-0272829e195a', 'concept'::public.curated_course_node_type, 'Time-temperature, cross-contamination, allergens, and illness awareness', null, 1),
  ('f3d80a6e-b1a7-4e73-bb2a-e1e8b1bceaf5', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '2be3a52b-bab9-4b6c-8a48-0272829e195a', 'concept'::public.curated_course_node_type, 'Water, air, laundry, pool/spa, and communicable-disease awareness', null, 2),
  ('181699cf-6b1d-412d-accb-403681527cc7', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '2be3a52b-bab9-4b6c-8a48-0272829e195a', 'concept'::public.curated_course_node_type, 'Inspection, logs, training, escalation, and corrective action', null, 3),
  ('61788f05-385a-417e-ba6d-109e5c1c9994', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'bb8da051-20e7-4acd-ae38-957464a4937e', 'subtopic'::public.curated_course_node_type, 'Law, ethics, security, and duty of care', 'Managers operate within legal obligations and ethical expectations that vary by jurisdiction.', 1),
  ('6a33ced0-5e79-4f28-a6f1-823fe34efdf1', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '61788f05-385a-417e-ba6d-109e5c1c9994', 'concept'::public.curated_course_node_type, 'Guest rights, contracts, negligence, privacy, accessibility, and discrimination awareness', null, 0),
  ('21105fb1-5177-4a4c-b89f-e807d0957494', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '61788f05-385a-417e-ba6d-109e5c1c9994', 'concept'::public.curated_course_node_type, 'Alcohol, food, employment, licensing, and consumer protection awareness', null, 1),
  ('653e0fa5-242b-4aa7-8371-63327d1bc45c', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '61788f05-385a-417e-ba6d-109e5c1c9994', 'concept'::public.curated_course_node_type, 'Security, keys, cash, violence, trafficking, lost property, and vulnerable guests', null, 2),
  ('6a431de6-d0f4-4575-8d6c-c32a3ba8e064', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '61788f05-385a-417e-ba6d-109e5c1c9994', 'concept'::public.curated_course_node_type, 'Ethical decision-making, conflicts, reporting, and documentation', null, 3),
  ('6dccd632-d32e-4410-b74c-37dc58ce295f', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'bb8da051-20e7-4acd-ae38-957464a4937e', 'subtopic'::public.curated_course_node_type, 'Risk and crisis readiness', 'Prepared organizations anticipate disruptions, protect life, communicate accurately, and restore service responsibly.', 2),
  ('515f0c99-4227-4606-a2e1-abd9f51ba206', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '6dccd632-d32e-4410-b74c-37dc58ce295f', 'concept'::public.curated_course_node_type, 'Hazard identification and risk assessment', null, 0),
  ('ebf6142e-35c1-439e-9883-80465368f700', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '6dccd632-d32e-4410-b74c-37dc58ce295f', 'concept'::public.curated_course_node_type, 'Fire, severe weather, outage, cyber incident, medical emergency, and active threat awareness', null, 1),
