  ('2affd979-332d-4f9d-a2ca-0dfa5feff717', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '6dccd632-d32e-4410-b74c-37dc58ce295f', 'concept'::public.curated_course_node_type, 'Business continuity, crisis communication, recovery, and after-action learning', null, 3);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b083415d-2809-4c66-b701-443c3240d90d', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', null, 'topic'::public.curated_course_node_type, 'Industry Case Analysis, Site Observation, and Integrative Career Plan', 'Integrates the course through structured field observation, evidence-based case analysis, cross-functional diagnosis, and a personal pathway for experiential learning.', 15),
  ('5ca64758-f116-46f2-9791-54c6e9927520', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'b083415d-2809-4c66-b701-443c3240d90d', 'subtopic'::public.curated_course_node_type, 'Structured site observation', 'Observation turns industry exposure into evidence rather than impressionistic praise or criticism.', 0),
  ('e691b357-5fd6-4e34-8d0e-eae513f036ee', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5ca64758-f116-46f2-9791-54c6e9927520', 'concept'::public.curated_course_node_type, 'Permission, professional conduct, privacy, and noninterference', null, 0),
  ('544a89ec-e19a-41cf-a5c9-457f1095a14a', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5ca64758-f116-46f2-9791-54c6e9927520', 'concept'::public.curated_course_node_type, 'Arrival, service flow, physical evidence, accessibility, and atmosphere', null, 1),
  ('42a9a938-89a4-437f-90e0-498e7847b485', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5ca64758-f116-46f2-9791-54c6e9927520', 'concept'::public.curated_course_node_type, 'Frontstage/backstage clues, staffing, technology, quality, and safety', null, 2),
  ('379bb21b-680a-45ef-b114-b90806a6e072', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', '5ca64758-f116-46f2-9791-54c6e9927520', 'concept'::public.curated_course_node_type, 'Field notes separating observation, interpretation, question, and implication', null, 3),
  ('d7585e70-21ab-4d33-90af-7acf7375f96d', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'b083415d-2809-4c66-b701-443c3240d90d', 'subtopic'::public.curated_course_node_type, 'Cross-functional case analysis', 'Hospitality problems rarely belong to one department, so students must connect guest, people, process, financial, and risk consequences.', 1),
  ('1e49e85a-d30c-4b23-8f2e-d60522005be5', 'd5e6f7a8-9b0c-4d20-9e29-3f4a5b6c7d10', 'd7585e70-21ab-4d33-90af-7acf7375f96d', 'concept'::public.curated_course_node_type, 'Problem statement, stakeholders, facts, assumptions, and missing data', null, 0),
