rand hotels, chains, franchises, and platforms"}, {"id": "5fd11d9b-4cb4-455e-80d2-c134f4e823f5", "type": "concept", "title": "Globalization and localization"}, {"id": "cfeedfce-238b-4db5-a249-7af11e7a358e", "type": "concept", "title": "Disruption, recovery, and changing traveler expectations"}], "description": "Industry history explains why today's brands, practices, labor systems, and travel patterns developed."}, {"id": "ac2db5e2-0edb-44f1-b7c7-01961f49c777", "type": "subtopic", "title": "Systems and interdependencies", "children": [{"id": "44f92357-8c07-49bf-b36e-0d353f8c4c1b", "type": "concept", "title": "Origins, transit, destinations, and return journey"}, {"id": "79706532-4c4d-4184-9d71-eca058f5e1a6", "type": "concept", "title": "Suppliers, intermediaries, infrastructure, and public services"}, {"id": "0c5c134d-4e70-4cdd-b042-54ed0a5d1431", "type": "concept", "title": "Communities, ecosystems, regulation, and institutions"}, {"id": "c0ea1537-bf00-4060-a2c1-2de3cb074623", "type": "concept", "title": "Feedback loops, externalities, shocks, and shared value"}], "description": "A guest experience relies on networks rather than a single department or firm."}]}, {"id": "18a99946-4293-4e3c-94a4-d392e8ad5732", "type": "topic", "title": "Industry Sectors, Business Models, and Career Pathways", "description": "Maps the major sectors and career families while helping students connect roles, competencies, work conditions, professional standards, and lifelong development.", "children": [{"id": "72f27853-3ee4-4c28-b3e5-8943afac59e3", "type": "subtopic", "title": "Sector landscape", "children": [{"id": "0ac01367-4dc1-4c85-84f3-58d95d9ca40e", "type": "concept", "title": "Hotels, resorts, alternative lodging, and clubs"}, {"id": "424b712c-f479-4bab-9e89-59cecf8690dc", "type": "concept", "title": "Restaurants, catering, institutional foodservice, and beverages"}, {"id": "5ec4a041-1b7a-4e78-b959-ae23cd2a0d4f", "type": "concept", "title": "Tourism, transportation, destinations, 