ntory and labor."}]}, {"id": "809b7471-2fe7-43b6-996b-948e36f63065", "type": "topic", "title": "Travel, Tourism, Destinations, and Visitor Mobility", "description": "Connects travel demand, transportation, intermediaries, attractions, destinations, impacts, and policy within the wider tourism system.", "children": [{"id": "dbdb1c02-28f3-4a23-9831-0a640f8e0139", "type": "subtopic", "title": "Tourism demand and trip systems", "children": [{"id": "b4a16de4-d22f-44d1-be30-46ae000c65fe", "type": "concept", "title": "Leisure, business, visiting friends/relatives, education, health, and special-interest travel"}, {"id": "a4cf2134-8875-4804-9053-a901a925a445", "type": "concept", "title": "Domestic, inbound, outbound, and international tourism"}, {"id": "5b123f16-d737-48e3-9e8f-3363dfc0edb5", "type": "concept", "title": "Push/pull motivation, seasonality, and source markets"}, {"id": "82665336-a992-4a8e-b43a-6fb6d7d5a115", "type": "concept", "title": "Trip chain, gateways, modes, and last-mile access"}], "description": "Travel decisions reflect motivation, time, income, access, information, and perceived risk."}, {"id": "407deb54-099c-4826-bbbb-3290c7b936da", "type": "subtopic", "title": "Intermediaries and tourism supply", "children": [{"id": "5402df27-8459-44e7-ae54-047213515ca4", "type": "concept", "title": "Tour operators, travel advisors, OTAs, and platforms"}, {"id": "0725871d-dba7-4e89-9564-429793e683ea", "type": "concept", "title": "Air, rail, road, cruise, and ground transport"}, {"id": "f537e1ea-e2b0-4bc2-89c4-8420b093f6f1", "type": "concept", "title": "Attractions, guides, visitor services, and destinations"}, {"id": "3c231621-4173-4678-a878-e6d7cf2b59e9", "type": "concept", "title": "Packaging, commissions, connectivity, and information"}], "description": "Tourism products are assembled and distributed across a fragmented network."}, {"id": "0f89dd24-a501-428b-9e23-15e961210f78", "type": "subtopic", "title": "Destination impacts and management", "children": [{"id": "0f1e9b74-c773-417a-b9fe-a151c645b632", "type": "concept", "title": "Economic contribution, jobs, leakage, and local linkages"}, {"id": "8ed73d88-02f2-4f13-9b47-c55196b44312", "type": "concept", "title": "Social, cultural, environmental, and resident impacts"}, {"id": "fa240566-8637-4103-8212-6003eb5890c4", "type": "concept", "title": "DMOs/DMMOs, policy, marketing, and stewardship"}, {"id": "bea36d13-48aa-40f8-8a0a-04a7c8b0b496", "type": "concept", "title": "Sustainability, resilience, overtourism, and visitor management awareness"}], "description": "Tourism creates value and pressure that destinations must govern collectively."}]}, {"id": "d5710131-4228-461e-87fd-17a502c35ff2", "type": "topic", "title": "Events, Conventions, Attractions, Recreation, and Entertainment", "description": "Extends the sector map to experience businesses whose capacity, programming, safety, sponsorship, and visitor-flow decisions shape destinations and hospitality demand.", "children": [{"id": "5181c9de-18e3-4f41-9068-f5bd7211b2cf", "type": "subtopic", "title": "Meetings and events ecosystem", "children": [{"id": "b318ee37-4ca6-4fda-96af-3da66f97dd4f", "type": "concept", "title": "Meetings, incentives, conventions, exhibitions, weddings, festivals, and mega-events"}, {"id": "ac6be72c-3019-4884-8c6a-81ab7c431e0e", "type": "concept", "title": "Venues, convention bureaus, planners, producers, and vendors"}, {"id": "a55d03ad-1980-415a-9288-7b482c6d1212", "type": "concept", "title": "Objectives, audience, program, budget, and timeline"}, {"id": "f7ffff44-bb16-4739-86e8-46376c3ab57f", "type": "concept", "title": "Bids, contracts, sponsorship, registration, and post-event evaluation"}], "description": "Events bring together clients, attendees, venues, suppliers, sponsors, destinations, and regulators."}, {"id": "7083cbf3-b82d-40dc-b6c1-8f438158b1b9", "type": "subtopic", "title": "Attractions and entertainment", "children": [{"id": "984ca3b8-7e95-4e11-a1d1-aa1624e01c31", "type": "concept", "title": "Theme parks, museums, heritage, nature, cultural, and retail attractions"}, {"id": "57fd0321-86f6-405f-aa8e-1edd9c7a2636", "type": "concept", "title": "Gaming, sports, live entertainment, recreation, and clubs awareness"}, {"id": "7b8c759a-bfa5-450b-9479-e5749ba2af4f", "type": "concept", "title": "Programming, interpretation, merchandising, and ancillary revenue"}, {"id": "6e73c67f-67ca-4723-822b-e82185e10de1", "type": "concept", "title": "Capacity, queues, dwell time, flow, accessibility, and safety"}], "description": "Attractions compete through distinctive content, capacity design, repeatability, and safe visitor flow."}, {"id": "66db2b3c-5c98-4b20-b191-976859afbca5", "type": "subtopic", "title": "Experience and destination effects", "children": [{"id": "065bd1db-4bba-4622-ac1f-e63e44c1d988", "type": "concept", "title": "Season extension and demand generation"}, {"id": "049bdb5a-2246-4229-9dab-56e51e2ec379", "type": "concept", "title": "Place identity, resident participation, and legacy"}, {"id": "75eaef6a-6cd3-46ad-874e-b1f7407753ff", "type": "concept", "title": "Congestion, waste, noise, security, and displacement"}, {"id": "1e7f7a06-92f9-4d56-8d2a-6ed72fe75eab", "type": "concept", "title": "Impact measurement and responsible event principles"}], "description": "Events and attractions can animate places while also creating crowding, cost, and community impacts."}]}, {"id": "9344ae5d-5aa3-4e29-a3d3-dfebd13c6cbb", "type": "topic", "title": "Ownership, Franchising, Management Contracts, and Asset Perspective", "description": "Distinguishes ownership, brand, and operation so students can understand incentives, fees, risk, standards, control, and stakeholder relationships.", "children": [{"id": "66c0049d-7f1e-4a0f-be09-07713c21a623", "type": "subtopic", "title": "Ownership and operating structures", "children": [{"id": "0a66658f-fda8-421d-9c29-07895e84b214", "type": "concept", "title": "Owner-operator and independent business"}, {"id": "632b37ef-9f2c-4a45-997d-bbafaa8695f5", "type": "concept", "title": "Franchise and license"}, {"id": "5338b67c-b8cc-4b3e-b3ff-543641c774c8", "type": "concept", "title": "Management contract and third-party operator"}, {"id": "6dc4603b-c605-406b-b803-c2521d915f8a", "type": "concept", "title": "Lease, concession, joint venture, and platform models awareness"}], "description": "The party that owns an asset may differ from the company that operates or brands it."}, {"id": "5a2df4b9-2a40-48d3-a10f-9d6a992df35d", "type": "subtopic", "title": "Brands, fees, standards, and control", "children": [{"id": "82e51eb3-1c16-4439-9414-18f68ed74d58", "type": "concept", "title": "Trademark, system, distribution, loyalty, and training"}, {"id": "339fd84f-09eb-4cd8-a4ac-f7ff2504c2c1", "type": "concept", "title": "Initial, royalty, marketing, reservation, and management fees"}, {"id": "4d803745-e465-4001-8f63-49970e65fc52", "type": "concept", "title": "Standards, audits, property improvement plans, and territory"}, {"id": "4b8b3a66-d7fe-44c9-b76b-6b0813a780f9", "type": "concept", "title": "Owner, operator, brand, lender, employee, and guest incentives"}], "description": "Students should understand what each party contributes, controls, earns, and risks."}, {"id": "f2b15f29-61d5-423c-ae73-9d7cf0dd257e", "type": "subtopic", "title": "Asset and lifecycle perspective", "children": [{"id": "55144920-5076-4b54-8cee-53379518f186", "type": "concept", "title": "Development, opening, stabilization, renovation, repositioning, and exit"}, {"id": "ae5dcd58-943c-4b07-98c4-89c7c0091d90", "type": "concept", "title": "Capital expenditure versus operating expense awareness"}, {"id": "b9329afa-3f3a-449f-850c-021316110c6a", "type": "concept", "title": "Real estate, location, concept, and market fit"}, {"id": "598f8846-562d-4047-8081-2a888dc3cdaa", "type": "concept", "title": "Owner return, operator performance, brand value, and stakeholder tradeoffs"}], "description": "Hospitality decisions affect both current operations and long-term asset value."}]}, {"id": "0f799039-f7ad-4ab3-81af-4d59f0eb638f", "type": "topic", "title": "Service Operations, Quality, Capacity, and Recovery", "description": "Builds an introductory operations lens for process flow, demand and capacity, queues, quality, failure prevention, complaint handling, and continuous improvement.", "children": [{"id": "0502855c-e3c3-4824-afa5-4c03e4d27c62", "type": "subtopic", "title": "Service process design", "children": [{"id": "3e3edaf6-316f-4441-84c3-83f002e11a00", "type": "concept", "title": "Guest actions, frontstage, backstage, and support processes"}, {"id": "36a09b56-6512-45d6-9c7f-6f49d3784a00", "type": "concept", "title": "Inputs, steps, handoffs, bottlenecks, and failure points"}, {"id": "d246e7ba-2bb3-4e72-905f-eb45fd5d46da", "type": "concept", "title": "Standardization versus customization"}, {"id": "a61c99cd-74ef-40ad-818d-972ec03ffcd9", "type": "concept", "title": "Poka-yoke, checklists, and visual management awareness"}], "description": "A service blueprint makes visible the work and handoffs behind a guest-facing promise."}, {"id": "633b8c47-7fba-4276-85cc-f84d2b5679c1", "type": "subtopic", "title": "Demand, capacity, and queues", "children": [{"id": "35b38763-429e-4935-ab47-c19eb0473f5e", "type": "concept", "title": "Forecasting and demand patterns"}, {"id": "68034cf2-28c6-4194-b605-fa06165fb1e9", "type": "concept", "title": "Fixed and flexible capacity"}, {"id": "6f4b0124-bc61-486e-8b26-c479ea7dcc74", "type": "concept", "title": "Queues, reservations, appointments, and virtual waits"}, {"id": "9d513f0d-e547-4181-8a0e-7aafab4b356b", "type": "concept", "title": "Scheduling, cross-training, yield awareness, and demand shaping"}], "description": "Hospitality capacity is perishable, demand fluctuates, and waiting strongly shapes perceived quality."}, {"id": "03c2a0b5-769b-4983-8074-e26fb89f6b6a", "type": "subtopic", "title": "Quality and service recovery", "children": [{"id": "827f7a85-2fa0-4a11-b59c-488b849a6d8d", "type": "concept", "title": "Technical versus functional quality"}, {"id": "6619d9bc-079f-42a5-b091-eb8b3e7e0d10", "type": "concept", "title": "Standards, inspection, feedback, and quality costs"}, {"id": "d37278f5-c956-4b38-9e94-5d0dd6fe112c", "type": "concept", "title": "Listen, acknowledge, apologize, solve, compensate, and follow up"}, {"id": "2acd2d92-e238-467c-819f-8e014c5475e6", "type": "concept", "title": "Root cause, escalation, empowerment, and continuous improvement"}], "description": "Errors are inevitable; effective recovery can restore fairness and trust while creating learning."}]}, {"id": "7d38118e-cd1a-450c-a60e-c0c026b6220e", "type": "topic", "title": "Hospitality Economics, Financial Logic, and Industry Metrics", "description": "Gives students the vocabulary to interpret demand, revenue, cost, productivity, profitability, and basic hotel, restaurant, event, and tourism indicators.", "children": [{"id": "a788d53d-6305-42fb-a785-206c284514c0", "type": "subtopic", "title": "Demand, revenue, cost, and profit", "children": [{"id": "292245b4-188c-4520-9123-d2e4986fdca5", "type": "concept", "title": "Volume, price, mix, revenue, variable/fixed cost, and contribution"}, {"id": "1b5fb85e-0f05-42a3-8d24-781cbbff6b26", "type": "concept", "title": "Labor, occupancy, food, distribution, utilities, and capital costs"}, {"id": "aa1c25cb-e3fa-4935-aa48-f80889bac8f2", "type": "concept", "title": "Profit, cash flow, break-even, and seasonality awareness"}, {"id": "1a4d1638-b93d-4362-9401-38ef8935d25e", "type": "concept", "title": "Inflation, exchange rates, economic cycles, and consumer confidence"}], "description": "Basic financial logic helps students connect guest and operating decisions to viability."}, {"id": "0b12bc40-4d8e-414a-aca4-795ea2d8d7b9", "type": "subtopic", "title": "Lodging metrics", "children": [{"id": "f0b3589c-d3af-4870-8f41-e5e4ef695900", "type": "concept", "title": "Available rooms, rooms sold, and occupancy"}, {"id": "1783c04e-c634-4477-93cb-cae421a4b287", "type": "concept", "title": "Average daily rate and RevPAR"}, {"id": "7e5c8e1b-8b44-4ad0-9edc-afbad2fd8bcd", "type": "concept", "title": "Market penetration, rate, and revenue indexes awareness"}, {"id": "973e8489-eefb-442f-be3b-b632a8c7c773", "type": "concept", "title": "Total revenue and profit metrics awareness"}], "description": "A small set of measures summarizes room demand, achieved price, and revenue productivity."}, {"id": "3004ce1a-8c49-4dbe-b79d-e719ae1b807e", "type": "subtopic", "title": "Foodservice, event, and tourism metrics", "children": [{"id": "f6a4c524-7121-4a74-8f09-92729a91e3a0", "type": "concept", "title": "Covers, check average, seat turnover, and sales per labor hour"}, {"id": "2a11d7d4-8db8-4aae-b5e2-887631e0a176", "type": "concept", "title": "Food cost, beverage cost, labor cost, waste, and prime cost awareness"}, {"id": "e6fd4b83-0211-460e-a05b-422468d7ec3f", "type": "concept", "title": "Attendance, utilization, spend per attendee, and event yield"}, {"id": "878df626-4e0d-46fd-afd6-e6c8e56a9a01", "type": "concept", "title": "Arrivals, nights, length of stay, spend, seasonality, and economic impact"}], "description": "Each sector needs measures matched to its capacity and value creation."}]}, {"id": "e56542ea-7d71-4031-ad5b-8014797f9ffd", "type": "topic", "title": "Marketing, Distribution, Sales, Loyalty, and the Digital Guest Journey", "description": "Shows how guests discover, compare, book, experience, review, and return—and how direct channels, intermediaries, pricing, CRM, and reputation interact.", "children": [{"id": "8e41dda3-c3c3-40f7-8d76-ba8b01c409d9", "type": "subtopic", "title": "Markets, brands, and value propositions", "children": [{"id": "f4bcc738-97d7-421c-ad6d-df895140d985", "type": "concept", "title": "Segmentation, targeting, personas, and jobs-to-be-done awareness"}, {"id": "d5a00511-3ad1-4bf2-b615-3f174bb210d9", "type": "concept", "title": "Positioning, brand promise, identity, and differentiation"}, {"id": "adff0a74-5c06-4a0a-86a5-42aada27ba09", "type": "concept", "title": "Product/service, price, place, promotion, people, process, and physical evidence"}, {"id": "8c713ddb-9ee0-4e07-bcc3-9f9c6b9d3835", "type": "concept", "title": "Cultural relevance, accessibility, and truthful claims"}], "description": "Marketing begins with choosing whom to serve and why the offer matters."}, {"id": "420b16f7-5b85-453b-9029-7dfe2b5df568", "type": "subtopic", "title": "Distribution and sales", "children": [{"id": "007a1d58-cda0-417e-9ab0-f50c47699fd8", "type": "concept", "title": "Direct web/mobile/voice and walk-in"}, {"id": "c25ea201-d6b4-4453-991f-2a309f990bff", "type": "concept", "title": "OTAs, GDS, wholesalers, tour operators, and travel advisors"}, {"id": "9c8b3197-e306-43c0-a1bf-c1f4ad960507", "type": "concept", "title": "Commissions, parity awareness, conversion, and channel mix"}, {"id": "ca5870b8-ca3b-44d6-b0f8-a7f55acf93cc", "type": "concept", "title": "Corporate, group, leisure, local, and partnership sales"}], "description": "Channels create reach but also cost, dependence, data tradeoffs, and possible conflict."}, {"id": "e4f76bd0-7c72-4cfb-8fd7-4fda56b84c3f", "type": "subtopic", "title": "CRM, reputation, and loyalty", "children": [{"id": "6bc487fe-875a-4a75-a07d-6bb764075e54", "type": "concept", "title": "Consent-based guest profiles and preferences"}, {"id": "d952b834-a617-4e7b-880f-8eae0a789a4b", "type": "concept", "title": "Email, mobile, social, and lifecycle communication"}, {"id": "8a8d392e-db15-4a74-af1b-fb1ffb1a786a", "type": "concept", "title": "Reviews, ratings, social listening, and response"}, {"id": "140b3d16-8ee5-44d5-ac36-d78c6eab3fa0", "type": "concept", "title": "Loyalty economics, recognition, personalization, and privacy"}], "description": "The post-purchase relationship shapes repeat business, referrals, recovery, and lifetime value."}]}, {"id": "27222bbd-1ffe-4bd5-a380-bdcc13fa1fbe", "type": "topic", "title": "People, Leadership, Workforce, and Inclusive Organizations", "description": "Introduces labor-intensive service leadership, staffing, culture, teamwork, employee experience, legal/ethical responsibilities, diversity, equity, inclusion, and well-being.", "children": [{"id": "62650090-ca1a-472c-9f26-e16fedd6bb1f", "type": "subtopic", "title": "Hospitality workforce system", "children": [{"id": "ea965990-8d06-4834-8b5f-79f4d634c62d", "type": "concept", "title": "Workforce planning, job design, and staffing"}, {"id": "618bc622-ef74-4f69-9f43-dfbcca51040e", "type": "concept", "title": "Recruitment, realistic job previews, selection, and onboarding"}, {"id": "815797e6-4cb1-4ef3-9b56-b0a15ebb5f20", "type": "concept", "title": "Scheduling, workload, productivity, and cross-training"}, {"id": "88bf857a-8681-4fce-8b0a-8c373305f647", "type": "concept", "title": "Turnover, retention, progression, and succession"}], "description": "Service quality depends on attracting, scheduling, developing, and retaining people in demanding operating environments."}, {"id": "bcc69c6b-3c5b-4e6a-9c4a-53ca4ca68412", "type": "subtopic", "title": "Frontline leadership and teamwork", "children": [{"id": "cf19a141-efa7-422d-8671-11281b8e10a6", "type": "concept", "title": "Leadership, motivation, and situational judgment"}, {"id": "53a9a7de-1223-4b22-a757-63a9db108673", "type": "concept", "title": "Briefings, delegation, coaching, feedback, and recognition"}, {"id": "4de5a75a-fd11-4a9f-8999-158c17286a91", "type": "concept", "title": "Team roles, communication, conflict, and psychological safety"}, {"id": "2b3c0e27-0116-4403-b249-47b541e6c265", "type": "concept", "title": "Empowerment, accountability, and service recovery support"}], "description": "Supervisors translate standards into daily priorities, coaching, coordination, and fair decisions."}, {"id": "0bff18e3-0eee-4a1a-8449-b4728a8c8b46", "type": "subtopic", "title": "Inclusion, well-being, and responsibility", "children": [{"id": "f403a315-c18f-427a-84d3-8443f6c1271e", "type": "concept", "title": "Diversity, equity, inclusion, belonging, and accessibility"}, {"id": "c4529925-f6c7-4dab-b56a-11d6a0e1ea4e", "type": "concept", "title": "Bias, harassment, discrimination, and respectful workplace expectations"}, {"id": "9ce8d1fd-ea98-49d1-b043-770bf6857d04", "type": "concept", "title": "Wages, tips, benefits, scheduling, labor rights, and ethical recruitment awareness"}, {"id": "1840dff7-9108-460d-9ecd-a3977ea0d5a1", "type": "concept", "title": "Emotional labor, burnout, safety, well-being, and speaking up"}], "description": "A hospitable organization must also be hospitable to its workforce."}]}, {"id": "b9e59208-d4d6-4ca4-8fed-dd45d7674f1b", "type": "topic", "title": "Sustainability, Accessibility, Community, and Social Responsibility", "description": "Connects environmental performance, community value, cultural respect, universal design, responsible sourcing, human rights, and credible reporting to hospitality decisions.", "children": [{"id": "82772413-cb2c-49fd-b4cb-6e7e0163e1a2", "type": "subtopic", "title": "Environmental operations", "children": [{"id": "ad6a5893-ecec-440d-a740-16365d0137d6", "type": "concept", "title": "Energy, water, refrigerants, and carbon"}, {"id": "c7a21a7a-fc8b-47e1-8ae4-691c631caaa9", "type": "concept", "title": "Food waste, materials, single-use items, and circularity"}, {"id": "992544f1-5622-46b1-b607-857684cc7f60", "type": "concept", "title": "Sustainable food, seafood, amenities, and procurement"}, {"id": "2eeba8ac-31ac-4db4-bb7d-55223fdfed9c", "type": "concept", "title": "Buildings, transport, biodiversity, and climate resilience"}], "description": "Hospitality organizations can reduce cost and impact through disciplined resource management and design."}, {"id": "4213e7f2-5b17-4d92-903e-ae4952842d11", "type": "subtopic", "title": "Accessibility and inclusive service", "children": [{"id": "172e4f01-d4e5-40d7-ae6d-f6cfeef90d10", "type": "concept", "title": "Physical, sensory, cognitive, digital, and communication access"}, {"id": "37da3410-c919-4f90-9bb0-91cb7e13296d", "type": "concept", "title": "Universal design and reasonable accommodation awareness"}, {"id": "3ed81c14-c6a8-4df5-b701-a19760fe4c45", "type": "concept", "title": "Accessible information, booking, rooms, dining, events, and evacuation"}, {"id": "8b4bfa64-b294-4342-8f5a-6889f9dd3bf6", "type": "concept", "title": "Disability etiquette, autonomy, companions, and service animals awareness"}], "description": "Universal design expands participation and improves service for guests with varied bodies, senses, cognition, language, and circumstances."}, {"id": "5ed47b2a-9f7e-4467-ae41-1a8120ec1f89", "type": "subtopic", "title": "Community, culture, and credible responsibility", "children": [{"id": "0a2322ac-a371-47f9-9ab9-dd5493def56d", "type": "concept", "title": "Local purchasing, employment, entrepreneurship, and community partnership"}, {"id": "1637d842-478d-4fe6-b5ea-96a1bee3e209", "type": "concept", "title": "Culture, heritage, Indigenous/community rights, and representation"}, {"id": "32a1f5ba-f43f-4104-8f0f-9ca3e42dfc7b", "type": "concept", "title": "Human trafficking awareness, child protection, and supply-chain human rights"}, {"id": "e1e21fec-b8f3-4d59-8252-94f0fd82222f", "type": "concept", "title": "Targets, evidence, reporting, certification, and greenwashing"}], "description": "Responsible hospitality creates local value and protects rights rather than treating community as scenery."}]}, {"id": "86e637ca-e625-4203-aeea-a2eeb34802b9", "type": "topic", "title": "Hospitality Technology, Data, AI, Cybersecurity, and Innovation", "description": "Surveys the digital stack and develops judgment about usefulness, integration, privacy, security, accessibility, automation, AI, and responsible innovation.", "children": [{"id": "cf068406-d6c6-422c-927a-6762aba76265", "type": "subtopic", "title": "Hospitality technology stack", "children": [{"id": "b3375dcf-a8b2-4cb0-ad95-8d19b3356adc", "type": "concept", "title": "PMS, POS, CRS, booking engine, channel manager, and GDS"}, {"id": "bce1d4ed-cf71-495c-8a84-b9e15f75f2ae", "type": "concept", "title": "CRM, loyalty, revenue, workforce, finance, procurement, and maintenance systems"}, {"id": "a0da1616-4bb0-4f14-872e-b52816114767", "type": "concept", "title": "Payments, mobile keys, kiosks, messaging, IoT, and guest-room technology"}, {"id": "916c52a1-1333-45dc-ab78-97cc6528a07a", "type": "concept", "title": "Interfaces, APIs, integration, vendor dependence, and data quality"}], "description": "Students need a functional map of systems before learning individual products."}, {"id": "5e2e16bd-d7f3-436a-859f-d285b0861230", "type": "subtopic", "title": "Data, analytics, and AI", "children": [{"id": "cfe70a9d-6863-4703-8319-1870e2e819a3", "type": "concept", "title": "Operational, guest, transaction, workforce, and market data"}, {"id": "625d08c8-9dd4-4417-a770-b44e5677b40b", "type": "concept", "title": "Descriptive, diagnostic, predictive, and prescriptive analytics awareness"}, {"id": "39af8f95-dc82-4a41-8855-9fa4facff13e", "type": "concept", "title": "Forecasting, personalization, chatbots, content, and automation use cases"}, {"id": "e4e2dec7-4396-480c-90af-00a5bb291a7e", "type": "concept", "title": "Bias, hallucination, transparency, human oversight, and measurement"}], "description": "Data can improve service and decisions when its meaning, quality, limits, and permissions are understood."}, {"id": "5e3750fa-228a-4e80-bbad-4abc50783171", "type": "subtopic", "title": "Cybersecurity, privacy, and innovation", "children": [{"id": "ac4b3d12-1fc4-4a88-85b0-ba51ac296f98", "type": "concept", "title": "Phishing, ransomware, payment, identity, and IoT risks"}, {"id": "d0ca82a9-3733-410f-9392-a4ac6a00442c", "type": "concept", "title": "Access control, updates, backups, incident reporting, and vendor risk"}, {"id": "6423e068-ea1c-4246-b3e7-60a34589f1df", "type": "concept", "title": "Consent, minimization, retention, sharing, and guest rights awareness"}, {"id": "f03c1f3d-6951-41d3-b4f2-56c747344804", "type": "concept", "title": "Problem discovery, pilots, change management, adoption, and responsible scaling"}], "description": "Hospitality's many systems, payments, identities, and connected devices create material digital risk."}]}, {"id": "bb8da051-20e7-4acd-ae38-957464a4937e", "type": "topic", "title": "Safety, Hygiene, Law, Ethics, Risk, and Crisis Readiness", "description": "Establishes duty of care and the operational disciplines that protect guests, employees, organizations, and communities during routine service and disruption.", "children": [{"id": "2be3a52b-bab9-4b6c-8a48-0272829e195a", "type": "subtopic", "title": "Hygiene, food safety, and public health", "children": [{"id": "dfbfde5b-ec90-4ee7-9a0c-6adf1eadde4a", "type": "concept", "title": "Personal hygiene, cleaning, sanitation, and pest control"}, {"id": "980a24b3-671c-4a5e-85e5-c5d9c21fe265", "type": "concept", "title": "Time-temperature, cross-contamination, allergens, and illness awareness"}, {"id": "f3d80a6e-b1a7-4e73-bb2a-e1e8b1bceaf5", "type": "concept", "title": "Water, air, laundry, pool/spa, and communicable-disease awareness"}, {"id": "181699cf-6b1d-412d-accb-403681527cc7", "type": "concept", "title": "Inspection, logs, training, escalation, and corrective action"}], "description": "Safe hospitality requires preventive systems, trained people, clean facilities, and reliable response."}, {"id": "61788f05-385a-417e-ba6d-109e5c1c9994", "type": "subtopic", "title": "Law, ethics, security, and duty of care", "children": [{"id": "6a33ced0-5e79-4f28-a6f1-823fe34efdf1", "type": "concept", "title": "Guest rights, contracts, negligence, privacy, accessibility, and discrimination awareness"}, {"id": "21105fb1-5177-4a4c-b89f-e807d0957494", "type": "concept", "title": "Alcohol, food, employment, licensing, and consumer protection awareness"}, {"id": "653e0fa5-242b-4aa7-8371-63327d1bc45c", "type": "concept", "title": "Security, keys, cash, violence, trafficking, lost property, and vulnerable guests"}, {"id": "6a431de6-d0f4-4575-8d6c-c32a3ba8e064", "type": "concept", "title": "Ethical decision-making, conflicts, reporting, and documentation"}], "description": "Managers operate within legal obligations and ethical expectations that vary by jurisdiction."}, {"id": "6dccd632-d32e-4410-b74c-37dc58ce295f", "type": "subtopic", "title": "Risk and crisis readiness", "children": [{"id": "515f0c99-4227-4606-a2e1-abd9f51ba206", "type": "concept", "title": "Hazard identification and risk assessment"}, {"id": "ebf6142e-35c1-439e-9883-80465368f700", "type": "concept", "title": "Fire, severe weather, outage, cyber incident, medical emergency, and active threat awareness"}, {"id": "78b12e1b-9de7-4c65-a894-e5195bc42d22", "type": "concept", "title": "Emergency roles, evacuation, shelter, accessibility, and guest accountability"}, {"id": "2affd979-332d-4f9d-a2ca-0dfa5feff717", "type": "concept", "title": "Business continuity, crisis communication, recovery, and after-action learning"}], "description": "Prepared organizations anticipate disruptions, protect life, communicate accurately, and restore service responsibly."}]}, {"id": "b083415d-2809-4c66-b701-443c3240d90d", "type": "topic", "title": "Industry Case Analysis, Site Observation, and Integrative Career Plan", "description": "Integrates the course through structured field observation, evidence-based case analysis, cross-functional diagnosis, and a personal pathway for experiential learning.", "children": [{"id": "5ca64758-f116-46f2-9791-54c6e9927520", "type": "subtopic", "title": "Structured site observation", "children": [{"id": "e691b357-5fd6-4e34-8d0e-eae513f036ee", "type": "concept", "title": "Permission, professional conduct, privacy, and noninterference"}, {"id": "544a89ec-e19a-41cf-a5c9-457f1095a14a", "type": "concept", "title": "Arrival, service flow, physical evidence, accessibility, and atmosphere"}, {"id": "42a9a938-89a4-437f-90e0-498e7847b485", "type": "concept", "title": "Frontstage/backstage clues, staffing, technology, quality, and safety"}, {"id": "379bb21b-680a-45ef-b114-b90806a6e072", "type": "concept", "title": "Field notes separating observation, interpretation, question, and implication"}], "description": "Observation turns industry exposure into evidence rather than impressionistic praise or criticism."}, {"id": "d7585e70-21ab-4d33-90af-7acf7375f96d", "type": "subtopic", "title": "Cross-functional case analysis", "children": [{"id": "1e49e85a-d30c-4b23-8f2e-d60522005be5", "type": "concept", "title": "Problem statement, stakeholders, facts, assumptions, and missing data"}, {"id": "50ae4456-76a2-4700-ba36-d51ef484ccf2", "type": "concept", "title": "Guest, operations, workforce, marketing, finance, technology, sustainability, and risk lenses"}, {"id": "b31bd25e-6358-4e54-989d-9729f37b57e6", "type": "concept", "title": "Alternatives, tradeoffs, feasibility, ethics, and recommendation"}, {"id": "98329a31-4471-43e4-900c-157cd4bfcc45", "type": "concept", "title": "Implementation steps, measures, and unintended consequences"}], "description": "Hospitality problems rarely belong to one department, so students must connect guest, people, process, financial, and risk consequences."}, {"id": "1c422825-c1ae-40a6-b9d8-35cb77fb9d02", "type": "subtopic", "title": "Career and learning integration", "children": [{"id": "5e44b475-6490-4afc-8fc7-41fc2fd5d910", "type": "concept", "title": "Strengths, values, interests, constraints, and preferred environments"}, {"id": "249327fe-3f6f-49a3-828e-c3cf81d4af21", "type": "concept", "title": "Two career hypotheses and informational interviews"}, {"id": "ece125a8-8455-4182-aaa1-151b829e08bb", "type": "concept", "title": "Work experience, internship, student organization, credential, and project plan"}, {"id": "34952f2a-88c2-4559-aeee-91732c9d235b", "type": "concept", "title": "Resume/portfolio evidence, feedback, milestones, and plan revision"}], "description": "A purposeful plan connects interests to experiments, relationships, evidence of skill, and reflection."}]}], "dbBacked": true}$ihosjson$::jsonb,
